import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.DOOm19uJ.js";const p=JSON.parse('{"title":"Multi-factor authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/configuration-server-core-mfa.md","filePath":"guide/deployment/configuration-server-core-mfa.md"}'),i={name:"guide/deployment/configuration-server-core-mfa.md"};function r(s,e,c,l,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="multi-factor-authentication" tabindex="-1">Multi-factor authentication <a class="header-anchor" href="#multi-factor-authentication" aria-label="Permalink to &quot;Multi-factor authentication&quot;">​</a></h1><p>Authup supports TOTP, recovery codes, email codes, and WebAuthn credentials as second factors. Enable the feature with <code>mfaEnabled</code> (<code>MFA_ENABLED</code>) and require interactive enrollment for every local user with <code>mfaRequired</code> (<code>MFA_REQUIRED</code>). <code>mfaRequired</code> can only be enabled together with <code>mfaEnabled</code>.</p><h2 id="enforcement-model" tabindex="-1">Enforcement model <a class="header-anchor" href="#enforcement-model" aria-label="Permalink to &quot;Enforcement model&quot;">​</a></h2><p>With MFA enabled, a local user who has any confirmed authenticator must complete a second-factor challenge during password login and before authorization-code issuance. <code>mfaRequired</code> additionally routes a device-less user through inline enrollment on the hosted <code>/authorize</code> page.</p><p>The following boundaries are intentional:</p><ul><li>A federated identity-provider login trusts the upstream provider as the authentication authority. The external callback establishes a session without challenging the user&#39;s local Authup authenticators, and <code>mfaRequired</code> does not force local enrollment on that callback. Configure and enforce MFA at the upstream provider. The bootstrap tokens report the external authentication method and no local OTP proof unless a later local challenge stamps the session.</li><li>Setting <code>mfaEnabled</code> to <code>false</code> disables both local MFA configuration and enforcement, including for users who already have confirmed authenticators. Authenticator rows are retained and become active again when MFA is re-enabled. Treat disabling this option as an authentication-policy downgrade.</li><li>The direct resource-owner password grant permits a device-less user to obtain the initial session even when <code>mfaRequired</code> is enabled. The hosted login uses that same bootstrap session to reach inline enrollment, which cannot be completed inside a single password-grant request. Restrict the <code>password</code> grant with each client&#39;s <code>grantTypes</code> allowlist and use the authorization code flow when enrollment must be enforced before issuing an application token.</li></ul><p>An external login that continues through the hosted authorization flow can still encounter the normal <code>/authorize</code> MFA backstop before a later client authorization code is issued. The bootstrap session created by the external callback itself is not locally MFA-gated.</p><h2 id="cache-availability" tabindex="-1">Cache availability <a class="header-anchor" href="#cache-availability" aria-label="Permalink to &quot;Cache availability&quot;">​</a></h2><p>MFA verification uses a per-user cache lock to serialize factor consumption. The lock has an owner token and is renewed while verification is in progress; renewal and release are conditional on that token so an expired owner cannot extend or delete a successor&#39;s lock.</p><p>Verification fails closed when the cache or lock is unavailable. This applies even to TOTP and recovery codes, whose counters and <code>used_at</code> stamps provide a persistent replay backstop, because allowing concurrent read-verify-save sections during an outage could accept the same factor twice. A configured Redis deployment should therefore include Redis availability in the login-path service-level objective.</p><p>The same fail-closed posture applies to the per-account attempt throttle that guards enrollment confirmation and challenge-code delivery: when the throttle counter cannot be read, those endpoints degrade to a retry-able throttled response (HTTP 429) rather than surfacing the outage as an internal 500.</p><h2 id="related-settings" tabindex="-1">Related settings <a class="header-anchor" href="#related-settings" aria-label="Permalink to &quot;Related settings&quot;">​</a></h2><ul><li><code>mfaFreshnessMaxAge</code> (<code>MFA_FRESHNESS_MAX_AGE</code>) controls how long a session&#39;s MFA proof satisfies an explicit <code>acr_values=urn:authup:mfa</code> step-up request.</li><li><code>mfaTicketMaxAge</code> (<code>MFA_TICKET_MAX_AGE</code>) controls the short-lived pending login ticket used by email and WebAuthn challenges.</li><li>Email authentication requires an SMTP transport. WebAuthn uses <code>publicUrl</code> as its relying-party origin.</li></ul><p>See the <a href="./configuration-server-core.html">server configuration reference</a> for all configuration formats and defaults.</p>',14)])])}const f=a(i,[["render",r]]);export{p as __pageData,f as default};
